    explanation: '降水の有無を予報する際、「あり」と予報する確率の閾値をどこに設定するかによって、空振り率（実際には降水がなかったのに予報した割合）と見逃し率（実際には降水があったのに予報しなかった割合）はトレードオフの関係になる。閾値を下げて「降水あり」の予報を出しやすくすると、実際の降水をより多く捉えられるため見逃し率は低下するが、その分、実際には降水がなかった事例でも「あり」と予報してしまう機会が増え空振り率が上昇しやすくなる。逆に閾値を上げて慎重に「あり」の予報を出すようにすると、空振り率は低下するが見逃し率が上がりやすくなる。このトレードオフを踏まえ、防災上どちらをより重視すべきかという観点から閾値の設定が検討される。\n【図解】\n★ポイント: 見逃し率と空振り率＝閾値設定によりトレードオフの関係、片方を下げると他方が上がりやすい\n○正: Aの通り、閾値を下げると見逃し率減・空振り率増\n×誤: Bの独立し同時改善、Cの下げると見逃し率上昇、Dの閾値と無関係はいずれも誤り\n→ 結論: 空振り率と見逃し率のトレードオフを正しく述べたAが正解（A）',
