    correctKey: 'A',
    explanation: '航空機の安全かつ効率的な運航には、出発地・目的地・飛行経路上の気象状況が大きく影響するため、航空会社や運航管理者は、空港における一定時間先までの気象予報であるTAF（航空路予報）、定時の実況気象を通報するMETAR、乱気流・着氷・火山灰等の航空機に危険な現象を伝えるSIGMET情報といった専門的な航空気象情報を総合的に活用している。これらの情報をもとに、就航可否の判断、目的地の天候悪化に備えた代替空港着陸用の追加燃料の搭載量の決定、悪天候域を避けるための迂回ルートの選定など、運航に関わる様々な意思決定が行われている。\n【図解】\n★ポイント: 航空気象情報（TAF・METAR・SIGMET）＝就航可否・燃料搭載・迂回ルート判断に活用\n○正: Aの通り、多様な航空気象情報が運航判断に用いられる\n×誤: Bの気象情報不使用、CのTAFに予報含まれず、Dの燃料搭載に考慮せずはいずれも誤り\n→ 結論: 航空機運航における気象情報活用を正しく述べたAが正解（A）',
