    explanation: 'アンサンブル予報は多数のメンバーによる離散的な予測値の集まりであるが、これを正規分布やより複雑な統計分布（歪度を考慮した分布等）で近似することで、連続的な確率密度関数（PDF）として表現する手法がある。この表現方法により、「30mm以上の降水確率」のようなあらかじめ定めた特定の閾値についての確率だけでなく、任意の閾値や範囲についての確率を柔軟に算出することができ、より詳細で豊かな確率的情報を提供することが可能になる。一般にアンサンブルのメンバー数が多いほど、この確率分布の形状をより精度よく推定できる。\n【図解】\n★ポイント: PDF表現＝アンサンブルの離散的な予測を連続的な確率分布として近似、柔軟な確率算出が可能\n○正: Aの通り、特定閾値に限定されない詳細な確率情報を提供\n×誤: Bの確率情報を含まない、Cの閾値超過確率算出不可、Dのメンバー少ないほど正確はいずれも誤り\n→ 結論: 確率密度関数による予測表現の利点を正しく述べたAが正解（A）',
